import { canonicalJson, sha256Json } from "./core.ts";
import { parseNativeRecords } from "./native-history.ts";

type RecordValue = Record<string, unknown>;
export interface NativeSourceObject { readonly id: string; readonly type: string; readonly body: RecordValue; }
export interface NativeSourceSnapshot {
  readonly schema: "easyeda-pro-control.document-source.v1";
  readonly document: RecordValue;
  readonly objects: readonly NativeSourceObject[];
  readonly sha256: string;
}

/** DOCHEAD client/updateTime/version are freshly generated by each export.
 * Object tickets are export ordering, not persisted object identity. No body
 * field or unknown document metadata is discarded from semantic comparison.
 */
export function parseDocumentSource(source: string): NativeSourceSnapshot {
  const records = parseNativeRecords(source);
  const first = records[0];
  if (first?.header["type"] !== "DOCHEAD" || first.body === null) {
    throw new Error("Document source must start with one DOCHEAD.");
  }
  const document = { ...first.body };
  delete document["client"]; delete document["updateTime"]; delete document["version"];
  if (typeof document["uuid"] !== "string" || document["uuid"].length === 0 ||
      !["PCB", "SCH", "SCH_PAGE", "SYMBOL", "FOOTPRINT"].includes(String(document["docType"]))) {
    throw new Error("Unsupported native source document identity.");
  }
  const objects: NativeSourceObject[] = [];
  const ids = new Set<string>();
  for (const entry of records.slice(1)) {
    const id = entry.header["id"];
    const type = entry.header["type"];
    if (typeof id !== "string" || id.length === 0 || ids.has(id) ||
        typeof type !== "string" || ["DOCHEAD", "DELETE_DOC", "DELETE"].includes(type) || entry.body === null) {
      throw new Error("Exported document source has missing, duplicate or deleted records.");
    }
    ids.add(id);
    objects.push({ id, type, body: entry.body });
  }
  objects.sort((a, b) => a.id.localeCompare(b.id));
  const snapshot = { schema: "easyeda-pro-control.document-source.v1" as const, document, objects };
  return { ...snapshot, sha256: sha256Json(snapshot) };
}

export interface NativeSourceDelta {
  readonly documentChanged: boolean;
  readonly added: readonly NativeSourceObject[];
  readonly removed: readonly NativeSourceObject[];
  readonly changed: readonly { readonly before: NativeSourceObject; readonly after: NativeSourceObject; readonly fields: readonly string[] }[];
}

export function compareDocumentSources(before: NativeSourceSnapshot, after: NativeSourceSnapshot): NativeSourceDelta {
  const oldObjects = new Map(before.objects.map((object) => [object.id, object]));
  const newObjects = new Map(after.objects.map((object) => [object.id, object]));
  return {
    documentChanged: canonicalJson(before.document) !== canonicalJson(after.document),
    added: after.objects.filter((object) => !oldObjects.has(object.id)),
    removed: before.objects.filter((object) => !newObjects.has(object.id)),
    changed: after.objects.flatMap((object) => {
      const previous = oldObjects.get(object.id);
      if (previous === undefined || canonicalJson(previous) === canonicalJson(object)) { return []; }
      const fields = [...new Set([...Object.keys(previous.body), ...Object.keys(object.body)])]
        .filter((key) => canonicalJson({ value: previous.body[key] }) !== canonicalJson({ value: object.body[key] })).toSorted();
      if (previous.type !== object.type) { fields.push("$type"); }
      return [{ before: previous, after: object, fields }];
    }),
  };
}

/** This string is facade-owned code, embedded in the exact runtime reader. */
export const NORMALIZE_DOCUMENT_SOURCE_CODE = `
const sourceLines = source.split("|\\n");
const sourceHead = sourceLines[0];
if (typeof sourceHead !== "string" || !sourceHead.startsWith('{"type":"DOCHEAD"}||')) throw new Error("Native source header is unsupported");
const sourceHeader = JSON.parse(sourceHead.slice(20));
if (typeof sourceHeader.client !== "string" || !/^[a-f0-9]{16}$/.test(sourceHeader.client) ||
    !Number.isSafeInteger(sourceHeader.updateTime) || sourceHeader.version !== String(sourceHeader.updateTime)) throw new Error("Native export metadata shape changed");
delete sourceHeader.client; delete sourceHeader.updateTime; delete sourceHeader.version;
sourceLines[0] = '{"type":"DOCHEAD"}||' + JSON.stringify(sourceHeader);
source = sourceLines.join("|\\n");
`;
